  docs.querySelectorAll('[data-analyst-clear]').forEach(b=>b.onclick=()=>safeRun(async()=>{readyToDelete();if(!confirm('Clear all current transaction records and tax fields from this document? Keep its original file. Saved compilations and preparation drafts remain separate.'))return;b.disabled=true;try{const doc=state.documents.find(d=>d.id===b.dataset.analystClear);Object.assign(doc,await api('tax-analyst/clear-records',{id:doc.id,revision:doc.revision,confirm:'CLEAR'}));editor.hidden=true;root.querySelector('#analyst-case-panel').hidden=true;render();message('Extracted records cleared; original retained')}finally{b.disabled=false}}));
