  root.querySelector('#analyst-builds').innerHTML=state.builds.filter(b=>b.year===selectedYear).map(b=>`<article class="card"><h4>${b.year} compilation · ${esc(localizedDate(b.created*1000))}</h4><p>${b.records.length} approved records · ${(b.tax_fields||[]).length} approved tax fields · ${b.unapproved_excluded} unapproved excluded</p><p>${esc(b.notice)}</p>${b.draft_id?'<button data-analyst-return="'+b.id+'">Open preparation list</button>':''}<button data-analyst-export="${b.id}">Download compilation JSON</button><button data-analyst-remove-build="${b.id}">Delete compilation snapshot</button></article>`).join('')||'<p>No compilations for this year.</p>';
  root.querySelectorAll('[data-analyst-return]').forEach(b=>b.onclick=()=>safeRun(()=>{taxSelectedYear=state.builds.find(x=>x.id===b.dataset.analystReturn).year;return show('tax_return_2026')}));
  root.querySelectorAll('[data-analyst-export]').forEach(b=>b.onclick=()=>{const build=state.builds.find(x=>x.id===b.dataset.analystExport);download('tax-preparation-'+build.year+'.json','application/json',JSON.stringify(build,null,2))});
