 async function analyze(doc,button,openEditor=true){
  if(dirty||caseDirty)throw Error('Save or discard edits before analysis');
  if(!root.querySelector('#analyst-consent').checked)throw Error('Consent is required before sending the full document to OpenAI');
  button.disabled=true;message('Analyzing document. Do not retry while the request is running.');
  try{const updated=await api('tax-analyst/analyze',{id:doc.id,revision:doc.revision,consent:true});Object.assign(doc,updated);await refreshSession();render();if(openEditor)edit(doc);message(updated.notice)}finally{button.disabled=false}
 }
 let dirty=false,polling=false,closed=false;
 const poll=setInterval(async()=>{if(closed||polling||dirty||caseDirty||batchBusy||document.hidden||!root.querySelector('#analyst-docs')||!(state.automation_jobs||[]).some(j=>['queued','running'].includes(j.state)))return;polling=true;try{const fresh=await api('tax-analyst/list');if(!closed&&!dirty&&!caseDirty&&!batchBusy&&root.querySelector('#analyst-docs')){state.documents=fresh.documents;state.automation_jobs=fresh.automation_jobs;await refreshSession();if(!closed&&!dirty&&!caseDirty&&!batchBusy)render()}}catch{}finally{polling=false}},15000);
 const warn=e=>{if(dirty||caseDirty||batchBusy||queue.has()){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',warn);
