function taxFieldHtml(fields){
 return '<h4>Tax form fields</h4><p>Verify the printed form, box, year, value and currency. Only approved W-2 boxes 1/2, 1099-INT boxes 1/4 and 1099-DIV boxes 1a/1b/4 populate income automatically. Other fields remain in the compilation for manual preparation. Do not include SSNs, account numbers or PINs. Do not approve duplicate amounts from statements or prior returns.</p>'+fields.map((f,n)=>'<fieldset class="tax-row" data-tax-field="'+n+'"><legend>Tax field '+(n+1)+'</legend>'+['form','box','label','value','currency','evidence'].map(k=>'<label>'+esc(title(k))+'<input name="'+k+'" maxlength="300" value="'+esc(f[k]||'')+'"></label>').join('')+'<label>Tax year<input name="year" type="number" min="2000" max="2100" value="'+(f.year||'')+'"></label><label><input name="approved" type="checkbox" '+(f.approved?'checked':'')+'> Approve verified field</label><button type="button" data-tax-field-remove="'+n+'">Remove tax field</button></fieldset>').join('')+'<button type="button" id="analyst-add-tax-field">Add tax field manually</button>';
}

function renderAnalystGroups(root,documents,year){
 const groups={};
 const minor=value=>{const [whole,fraction='']=String(value).split('.');return BigInt(whole)*100n+BigInt((fraction+'00').slice(0,2))};
 const decimal=amount=>String(amount/100n)+'.'+String(amount%100n).padStart(2,'0');
 for(const d of documents.filter(d=>d.year===year)){
  const key=d.document_type||'auto',g=groups[key]||(groups[key]={documents:0,records:0,fields:0,approved:0,totals:{}});g.documents++;
  for(const r of d.records||[]){g.records++;g.approved+=Number(r.approved);const bucket=r.currency+' / '+r.kind+' / '+(r.approved?'approved':'unreviewed');g.totals[bucket]=(g.totals[bucket]||0n)+minor(r.amount)}
  for(const f of d.tax_fields||[]){g.fields++;const form=f.form.toUpperCase().replaceAll(' ',''),box=f.box.toLowerCase().replace(/^box/,'').trim(),known={'W-2':['1','2'],'1099-INT':['1','4'],'1099-DIV':['1a','1b','4']};if(!known[form]?.includes(box)||!/^\d+(\.\d{1,2})?$/.test(f.value))continue;const bucket=f.currency+' / '+form+' box '+box+' / '+(f.approved?'approved':'unreviewed');g.totals[bucket]=(g.totals[bucket]||0n)+minor(f.value)}
 }
 root.querySelector('#analyst-groups').innerHTML=Object.entries(groups).map(([name,g])=>'<article class="card"><h4>'+esc(name)+'</h4><p>'+g.documents+' documents · '+g.records+' transactions · '+g.fields+' tax fields · '+g.approved+' approved transactions</p>'+Object.entries(g.totals).map(([bucket,amount])=>'<p>'+esc(bucket)+': '+esc(decimal(amount))+'</p>').join('')+'</article>').join('')||'<p>No uploads for this year.</p>';
}
async function showTaxAmendments(){
 const [catalog,items,analyst,drafts]=await Promise.all([api('tax-years'),api('tax-prep/amendments'),api('tax-analyst/list'),api('tax-prep/returns')]);
 content.innerHTML='<section><h2>Amended tax preparation</h2><p>Upload the originally filed return and supporting corrections through Tax analyst. Approve the extracted fields, then compare original amounts with revised preparation. This produces a private amendment worksheet, not a completed Form 1040-X or a certified maximum refund.</p><label>Tax year<select id="amend-year">'+catalog.years.map(y=>'<option>'+y+'</option>').join('')+'</select></label><button id="amend-create">Create amendment workspace</button><button data-go="tax_analyst">Upload / analyze tax records</button><p>Refund-claim deadlines, original refunds or credits, later payments, IRS changes, amended schedules and filing authorization need separate review. E-filing availability depends on the year and provider; older returns may require paper filing.</p><a href="https://www.irs.gov/instructions/i1040x" target="_blank" rel="noopener noreferrer">IRS Form 1040-X instructions</a></section><section><h3>Your amendment workspaces</h3>'+items.map(a=>'<p><button data-amend-open="'+a.id+'">'+a.year+' amendment · '+esc(localizedDate(a.updated*1000))+'</button></p>').join('')+'</section><section id="amend-editor" hidden></section>';
 goButtons();content.querySelector('#amend-create').onclick=()=>safeRun(async()=>{const row=await api('tax-prep/amendment-create',{year:Number(content.querySelector('#amend-year').value)});items.unshift(row);edit(row)});
 content.querySelectorAll('[data-amend-open]').forEach(b=>b.onclick=()=>edit(items.find(a=>a.id===b.dataset.amendOpen)));
 function edit(row){
  const box=content.querySelector('#amend-editor');box.hidden=false;
  box.innerHTML='<h3>'+row.year+' amendment worksheet</h3><p>'+esc(row.notice)+'</p><p>Corrected amounts source: '+esc(row.corrected_source)+'</p><form id="amend-form">'+['original','corrected'].map(section=>'<fieldset><legend>'+title(section)+' summary (USD)</legend>'+Object.entries({agi:'Adjusted gross income',taxable_income:'Taxable income',total_tax:'Total tax',total_payments:'Total payments'}).map(([key,label])=>'<label>'+esc(label)+'<input name="'+section+'_'+key+'" type="number" step="0.01" '+(key==='agi'?'':'min="0"')+' value="'+esc(row[section]?.[key]||'')+'"></label>').join('')+'</fieldset>').join('')+'<label>Explanation of changes<textarea name="reason" maxlength="4000">'+esc(row.reason)+'</textarea></label><label><input name="original_verified" type="checkbox" '+(row.original_verified?'checked':'')+'> I checked the original return and IRS adjustments.</label><button>Save & calculate changes</button></form><h4>Original / Change / Corrected</h4>'+table(row.comparison.map(x=>({item:x.label,original:x.original_cents===null?'Missing':formatMoneyMinor(x.original_cents,'USD'),change:x.change_cents===null?'Missing':formatMoneyMinor(x.change_cents,'USD'),corrected:x.corrected_cents===null?'Missing':formatMoneyMinor(x.corrected_cents,'USD')})),['item','original','change','corrected'])+'<label>Approved original-return source<select id="amend-document"><option value="">Choose original return</option>'+analyst.documents.filter(d=>d.year===row.year).map(d=>'<option value="'+d.id+'">'+esc(d.name)+'</option>').join('')+'</select></label><button id="amend-original">Import approved original 1040 summary</button><label>Corrected preparation with a supported saved projection<select id="amend-draft"><option value="">Choose corrected preparation</option>'+drafts.filter(d=>d.year===row.year).map(d=>'<option value="'+d.id+'">'+esc(d.name)+'</option>').join('')+'</select></label><button id="amend-corrected">Import limited projected corrected amounts</button><button id="amend-export">Download amendment worksheet</button><button id="amend-delete">Delete amendment workspace</button>';
  const update=updated=>{Object.assign(row,updated);edit(row)};
  box.querySelector('form').onsubmit=e=>{e.preventDefault();safeRun(async()=>{const d=Object.fromEntries(new FormData(e.target)),original={},corrected={};for(const key of ['agi','taxable_income','total_tax','total_payments']){original[key]=d['original_'+key];corrected[key]=d['corrected_'+key]}update(await api('tax-prep/amendment-save',{id:row.id,revision:row.revision,original,corrected,reason:d.reason,original_verified:e.target.elements.original_verified.checked}));message('Amendment changes saved. Additional refund and filing remain unverified.')})};
  box.querySelector('#amend-original').onclick=()=>safeRun(async()=>update(await api('tax-prep/amendment-import-original',{id:row.id,revision:row.revision,document_id:box.querySelector('#amend-document').value})));
  box.querySelector('#amend-corrected').onclick=()=>safeRun(async()=>update(await api('tax-prep/amendment-import-projection',{id:row.id,revision:row.revision,draft_id:box.querySelector('#amend-draft').value})));
  box.querySelector('#amend-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(row,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.year+'-amendment-NOT-FOR-FILING.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  box.querySelector('#amend-delete').onclick=()=>safeRun(async()=>{if(!confirm('Delete this amendment workspace? Original documents and linked preparations remain separate.'))return;await api('tax-prep/amendment-delete',{id:row.id,confirm:'DELETE'});await showTaxAmendments()});
 }
}

